-- ---------- 新規ユーザーへの自動コピー ----------
create or replace function public.seed_reference_templates()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.references (id, user_id, grape, type, country, region, data)
  select t.id, new.id, t.grape, t.type, t.country, t.region, t.data
  from public.reference_templates t
  on conflict (user_id, id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created_seed_refs on auth.users;
create trigger on_auth_user_created_seed_refs
  after insert on auth.users
  for each row execute function public.seed_reference_templates();

-- ---------- すでに登録済みで、模範回答を1件も持っていない人にも配る ----------
insert into public.references (id, user_id, grape, type, country, region, data)
select t.id, u.id, t.grape, t.type, t.country, t.region, t.data
from auth.users u
cross join public.reference_templates t
where not exists (select 1 from public.references r where r.user_id = u.id)
on conflict (user_id, id) do nothing;
